<?php require_once __DIR__.'/../_init.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['akad','resepsi'] as $j){$q=$pdo->prepare('INSERT INTO acara(jenis,tanggal,jam_mulai,jam_selesai,nama_lokasi,alamat,maps_url) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE tanggal=VALUES(tanggal),jam_mulai=VALUES(jam_mulai),jam_selesai=VALUES(jam_selesai),nama_lokasi=VALUES(nama_lokasi),alamat=VALUES(alamat),maps_url=VALUES(maps_url)');$q->execute([$j,$_POST['tanggal_'.$j],$_POST['jam_mulai_'.$j],$_POST['jam_selesai_'.$j]?:null,trim($_POST['nama_lokasi_'.$j]),trim($_POST['alamat_'.$j]),trim($_POST['maps_url_'.$j])]);}flash('success','Acara disimpan.');redirect('index.php');}$ev=[];foreach($pdo->query('SELECT * FROM acara') as $x)$ev[$x['jenis']]=$x;admin_header('Acara');?><div class="admin-card"><h1>Akad & Resepsi</h1><form method="post" class="form"><?=csrf_field()?><div class="grid2"><?php foreach(['akad','resepsi'] as $j):$x=$ev[$j]??[];?><div class="admin-card"><h2><?=ucfirst($j)?></h2><div class="field"><label>Tanggal</label><input type="date" name="tanggal_<?=$j?>" value="<?=e($x['tanggal']??'')?>"></div><div class="grid2"><div class="field"><label>Mulai</label><input type="time" name="jam_mulai_<?=$j?>" value="<?=e($x['jam_mulai']??'')?>"></div><div class="field"><label>Selesai</label><input type="time" name="jam_selesai_<?=$j?>" value="<?=e($x['jam_selesai']??'')?>"></div></div><div class="field"><label>Lokasi</label><input name="nama_lokasi_<?=$j?>" value="<?=e($x['nama_lokasi']??'')?>"></div><div class="field"><label>Alamat</label><textarea name="alamat_<?=$j?>"><?=e($x['alamat']??'')?></textarea></div><div class="field"><label>Google Maps</label><input name="maps_url_<?=$j?>" value="<?=e($x['maps_url']??'')?>"></div></div><?php endforeach;?></div><button class="btn">Simpan</button></form></div><?php admin_footer();?>
